const root = $json;
const headers = root.headers || {};
const receivedKey = String(headers['x-api-key'] || headers['X-API-Key'] || '');
const expectedKey = String($env.N8N_API_KEY || '');
if (!expectedKey || receivedKey !== expectedKey) throw new Error('Acesso não autorizado.');

const b = root.body ?? root;
const activity = b.activity || {};
const answer = String(b.answer || '').trim();
if (!answer) throw new Error('Resposta obrigatória.');

const prompt = `Você é o avaliador pedagógico do RS English.
Avalie a resposta do aluno de forma justa, de acordo com a atividade e o nível informado.

ATIVIDADE
Título: ${activity.title || ''}
Tipo: ${activity.type || ''}
Habilidade: ${activity.skill || ''}
Nível: ${activity.level || ''}
Instruções: ${activity.instructions || ''}
Conteúdo: ${JSON.stringify(activity.content || {})}

RESPOSTA DO ALUNO
${answer}

Retorne SOMENTE JSON válido:
{
  "score": 0,
  "feedback": "",
  "corrections": [],
  "vocabulary": []
}

Regras:
- score de 0 a 100;
- feedback curto, acolhedor e específico;
- não invente requisitos ausentes;
- em resposta aberta, avalie adequação, clareza, gramática e vocabulário no nível esperado;
- corrections deve conter no máximo 2 correções relevantes;
- vocabulary deve conter no máximo 3 palavras ou expressões relevantes da resposta, com word, translation, definition_en, example, level e category;
- não inclua artigos, pronomes ou auxiliares isolados.`;

return [{json:{...b,prompt}}];

const r = $json;
let text = r.output_text;
if (!text && Array.isArray(r.output)) {
  const parts = [];
  for (const item of r.output) for (const c of (item.content || [])) if (typeof c.text === 'string') parts.push(c.text);
  text = parts.join('\n');
}
text = String(text || '').replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/```$/i,'').trim();
let result;
try { result = JSON.parse(text); } catch { result = {score:70,feedback:'Resposta registrada para revisão.',corrections:[],vocabulary:[]}; }
result.score = Math.max(0, Math.min(100, Number(result.score || 0)));
result.feedback = String(result.feedback || 'Resposta avaliada.');
result.corrections = Array.isArray(result.corrections) ? result.corrections.slice(0,2) : [];
result.vocabulary = Array.isArray(result.vocabulary) ? result.vocabulary.slice(0,3) : [];
return [{json:result}];
